/**
 * contracts.ts
 *
 * Maps chainId → Vantage contract addresses.
 * Values are sourced from addresses.ts (auto-generated by `pnpm sync`).
 *
 * Usage:
 *   import { getVantageContractAddress } from "vantage/contracts";
 *   const addr = getVantageContractAddress(chainId, "VantageNftVault");
 */

import { ARBITRUM, ARBITRUM_SEPOLIA } from "config/chains";

import {
  ARBITRUM_SEPOLIA_VANTAGE_NAV_ORACLE,
  ARBITRUM_SEPOLIA_VANTAGE_NFT_VAULT,
  ARBITRUM_SEPOLIA_VANTAGE_POSITION_BRIDGE,
  ARBITRUM_SEPOLIA_VANTAGE_POSITION_CONTROLLER,
  ARBITRUM_SEPOLIA_VANTAGE_REWARD_ROUTER,
  ARBITRUM_SEPOLIA_VANTAGE_SHOP_VAULT,
  ARBITRUM_VANTAGE_NAV_ORACLE,
  ARBITRUM_VANTAGE_NFT_VAULT,
  ARBITRUM_VANTAGE_POSITION_BRIDGE,
  ARBITRUM_VANTAGE_POSITION_CONTROLLER,
  ARBITRUM_VANTAGE_REWARD_ROUTER,
  ARBITRUM_VANTAGE_SHOP_VAULT,
} from "./addresses";

// ---------------------------------------------------------------------------
// Contract name registry
// ---------------------------------------------------------------------------

export type VantageContractName =
  | "VantageNftVault"
  | "VantageShopVault"
  | "VantagePositionController"
  | "VantagePositionBridge"
  | "VantageRewardRouter"
  | "VantageNavOracle";

type VantageAddressMap = Record<VantageContractName, string>;

const VANTAGE_CONTRACTS: Record<number, VantageAddressMap> = {
  [ARBITRUM]: {
    VantageNftVault: ARBITRUM_VANTAGE_NFT_VAULT,
    VantageShopVault: ARBITRUM_VANTAGE_SHOP_VAULT,
    VantagePositionController: ARBITRUM_VANTAGE_POSITION_CONTROLLER,
    VantagePositionBridge: ARBITRUM_VANTAGE_POSITION_BRIDGE,
    VantageRewardRouter: ARBITRUM_VANTAGE_REWARD_ROUTER,
    VantageNavOracle: ARBITRUM_VANTAGE_NAV_ORACLE,
  },
  [ARBITRUM_SEPOLIA]: {
    VantageNftVault: ARBITRUM_SEPOLIA_VANTAGE_NFT_VAULT,
    VantageShopVault: ARBITRUM_SEPOLIA_VANTAGE_SHOP_VAULT,
    VantagePositionController: ARBITRUM_SEPOLIA_VANTAGE_POSITION_CONTROLLER,
    VantagePositionBridge: ARBITRUM_SEPOLIA_VANTAGE_POSITION_BRIDGE,
    VantageRewardRouter: ARBITRUM_SEPOLIA_VANTAGE_REWARD_ROUTER,
    VantageNavOracle: ARBITRUM_SEPOLIA_VANTAGE_NAV_ORACLE,
  },
};

// ---------------------------------------------------------------------------
// Lookup helper
// ---------------------------------------------------------------------------

export function getVantageContractAddress(chainId: number, name: VantageContractName): string {
  const map = VANTAGE_CONTRACTS[chainId];
  if (!map) {
    throw new Error(`Vantage contracts not configured for chainId: ${chainId}`);
  }
  return map[name];
}
